from __future__ import annotations

import argparse
import base64
import io
import json
import sys
import threading
from pathlib import Path

import cv2
import numpy as np
import torch
from PIL import Image


_CACHE = {}
_LOAD_LOCK = threading.Lock()


def _load_model(repo_path: Path, weights_path: Path):
    key = (str(repo_path.resolve()), str(weights_path.resolve()))
    if key in _CACHE:
        return _CACHE[key]
    sys.path.insert(0, str(repo_path.resolve()))
    from models.common import DetectMultiBackend

    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    with _LOAD_LOCK:
        original_load = torch.load

        def trusted_checkpoint_load(*args, **kwargs):
            kwargs.setdefault("weights_only", False)
            return original_load(*args, **kwargs)

        torch.load = trusted_checkpoint_load
        try:
            model = DetectMultiBackend(
                str(weights_path), device=device, fp16=device.type == "cuda"
            )
        finally:
            torch.load = original_load
    _CACHE[key] = (model, device)
    return model, device


def _encode_png(rgb: np.ndarray) -> str:
    buffer = io.BytesIO()
    Image.fromarray(rgb).save(buffer, format="PNG")
    return base64.b64encode(buffer.getvalue()).decode("ascii")


def predict(
    input_path: str,
    weights_path: str,
    repo_path: str,
    output_dir: str,
    confidence_threshold: float = 0.25,
    iou_threshold: float = 0.45,
    image_size: int = 640,
) -> dict:
    repo = Path(repo_path)
    model, device = _load_model(repo, Path(weights_path))
    from utils.augmentations import letterbox
    from utils.general import non_max_suppression, scale_boxes

    source = cv2.imread(input_path, cv2.IMREAD_COLOR)
    if source is None:
        raise ValueError(f"Unable to read image: {input_path}")
    resized = letterbox(source, (image_size, image_size), stride=model.stride, auto=True)[0]
    tensor = torch.from_numpy(resized.transpose((2, 0, 1))[::-1].copy()).to(device)
    tensor = tensor.half() if model.fp16 else tensor.float()
    tensor = tensor[None] / 255.0
    with torch.no_grad():
        raw = model(tensor)
        predictions = non_max_suppression(
            raw[0][1], confidence_threshold, iou_threshold, max_det=300
        )[0]
    detections = []
    overlay = source.copy()
    if len(predictions):
        predictions[:, :4] = scale_boxes(
            tensor.shape[2:], predictions[:, :4], source.shape
        ).round()
        for x1, y1, x2, y2, confidence, class_index in predictions.cpu().tolist():
            class_index = int(class_index)
            label = str(model.names[class_index])
            if label != "fracture":
                continue
            detections.append(
                {
                    "label": label,
                    "class_id": class_index,
                    "confidence": float(confidence),
                    "bbox_xyxy": [int(x1), int(y1), int(x2), int(y2)],
                }
            )
            cv2.rectangle(
                overlay, (int(x1), int(y1)), (int(x2), int(y2)), (20, 40, 240), 3
            )
    detections.sort(key=lambda item: item["confidence"], reverse=True)
    output = Path(output_dir)
    output.mkdir(parents=True, exist_ok=True)
    overlay_path = output / f"{Path(input_path).stem}_grazped_yolov9.png"
    cv2.imwrite(str(overlay_path), overlay)
    rgb = cv2.cvtColor(overlay, cv2.COLOR_BGR2RGB)
    result = {
        "model": "GRAZPEDWRI-DX YOLOv9-E",
        "detections": detections,
        "fracture_detected": any(item["label"] == "fracture" for item in detections),
        "fracture_max_confidence": max(
            (item["confidence"] for item in detections if item["label"] == "fracture"),
            default=0.0,
        ),
        "confidence_threshold": confidence_threshold,
        "image_b64": _encode_png(rgb),
        "output_file": str(overlay_path),
    }
    (output / f"{Path(input_path).stem}_result.json").write_text(
        json.dumps({key: value for key, value in result.items() if key != "image_b64"}, indent=2)
        + "\n"
    )
    return result


def _cli() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("input_path")
    parser.add_argument("--weights", required=True)
    parser.add_argument("--repo", required=True)
    parser.add_argument("--output-dir", required=True)
    parser.add_argument("--confidence", type=float, default=0.25)
    parser.add_argument("--iou", type=float, default=0.45)
    args = parser.parse_args()
    result = predict(
        args.input_path,
        args.weights,
        args.repo,
        args.output_dir,
        args.confidence,
        args.iou,
    )
    print(json.dumps({key: value for key, value in result.items() if key != "image_b64"}, indent=2))


